using var pe=new PEReader(File.OpenRead(typeof(HeaderEntryReadinessState).Assembly.Location));var md=pe.GetMetadataReader();
var ops=typeof(OpCodes).GetFields().Where(f=>f.FieldType==typeof(OpCode)).Select(f=>(OpCode)f.GetValue(null)!).ToDictionary(x=>(ushort)x.Value);
(List<string> calls,List<string> fields) Body(string method){var td=md.TypeDefinitions.Select(h=>md.GetTypeDefinition(h)).Single(t=>md.GetString(t.Name)=="GeneralUiProvider");var m=td.GetMethods().Select(h=>md.GetMethodDefinition(h)).Single(x=>md.GetString(x.Name)==method);var bytes=pe.GetMethodBody(m.RelativeVirtualAddress).GetILBytes()!;var calls=new List<string>();var fields=new List<string>();
 for(int i=0;i<bytes.Length;){ushort k=bytes[i++];if(k==0xfe)k=(ushort)(0xfe00|bytes[i++]);var op=ops[k];if(op.OperandType==OperandType.InlineMethod){var h=MetadataTokens.EntityHandle(BitConverter.ToInt32(bytes,i));if(h.Kind==HandleKind.MemberReference)calls.Add(md.GetString(md.GetMemberReference((MemberReferenceHandle)h).Name));else if(h.Kind==HandleKind.MethodDefinition)calls.Add(md.GetString(md.GetMethodDefinition((MethodDefinitionHandle)h).Name));}if(op.OperandType==OperandType.InlineField){var h=MetadataTokens.EntityHandle(BitConverter.ToInt32(bytes,i));if(h.Kind==HandleKind.FieldDefinition)fields.Add(md.GetString(md.GetFieldDefinition((FieldDefinitionHandle)h).Name));}i+=op.OperandType switch{OperandType.InlineNone=>0,OperandType.ShortInlineBrTarget or OperandType.ShortInlineI or OperandType.ShortInlineVar=>1,OperandType.InlineVar=>2,OperandType.InlineI8 or OperandType.InlineR=>8,OperandType.InlineSwitch=>4+4*BitConverter.ToInt32(bytes,i),_=>4};}return(calls,fields);}
