var output=new{status=failed==0?"PASS":"FAIL",count=cases.Count,failed,library_sha256=Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(HeaderEntryReadinessState).Assembly.Location))).ToLowerInvariant(),scope="Actual managed readiness policy + actual candidate PE call graph. Synthetic lifetimes are CPU cases, never native proof; natural first-home native separately required.",tests=cases};Console.WriteLine(JsonSerializer.Serialize(output,new JsonSerializerOptions{WriteIndented=true}));return failed==0?0:1;
